import re,sys
for fn in ["matter.py","life.py","energy.py","earth.py"]:
    t=open(fn).read()
    for p,new in list(NEW.items()):
        i=t.find('"'+p+'"')
        if i<0: continue
        j=t.index("],",i)  # نهاية قائمة البدائل
        k=t.index("[",i)
        opts=re.findall(r'"((?:[^"\\]|\\.)*)"',t[k:j])
        assert len(opts)==4,(p,opts)
        t=t[:k]+"["+",".join('"'+s+'"' for s in [opts[0]]+new)+t[j:]
        del NEW[p]
    open(fn,"w").write(t)
print("not found:",list(NEW))
